//! The improved elastic image pair method against reference data of MultiOptPy's `ieipmain`
//! on a Lennard-Jones pair of structures (`tests/golden/ieip_*.json`, generated by
//! `tools/golden/run_ieip_reference.py`): the run is repeated with the state machine and every
//! pair of structures it evaluates, the energies, `beta`, the separation after every step,
//! and the iteration of convergence must agree with MultiOptPy's.
//!
//! This file is part of mopt-rs.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod mop_units;

use std::path::PathBuf;
use std::sync::Arc;

use faer::Col;
use mopt_rs::cli::bias::parse_biases;
use mopt_rs::cli::option::parser;
use mopt_rs::cli::spec::IEIPMAIN;
use mopt_rs::core_infra::json::JsonValue;
use mopt_rs::domain::{positions, Bohr, Element, EvalRequest, MolecularSystem, SpinCharge};
use mopt_rs::path::ieip::{ElasticImagePair, IeipAction, IeipEnd, IeipSettings, ImageValue};
use mopt_rs::pes::term::{PesTerm, TermContext};

fn golden(name: &str) -> JsonValue {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    JsonValue::parse(&text).unwrap()
}

fn floats(v: &JsonValue) -> Vec<f64> {
    match v.as_array() {
        Some(items) => items.iter().flat_map(floats).collect(),
        None => vec![v.as_f64().unwrap()],
    }
}

fn bohr(v: &JsonValue) -> Col<f64> {
    let x = floats(v);
    Col::from_fn(x.len(), |k| mop_units::mop_bohr(x[k]))
}

fn argon(point: &Col<f64>) -> MolecularSystem {
    let atoms = point.nrows() / 3;
    let element = Element::parse_token("Ar").unwrap();
    let pos: Vec<[f64; 3]> = (0..atoms)
        .map(|a| [point[3 * a], point[3 * a + 1], point[3 * a + 2]])
        .collect();
    MolecularSystem::new(
        vec![element; atoms],
        &positions::<Bohr>(&pos),
        SpinCharge::default(),
        None,
    )
    .unwrap()
}

fn strings(v: &JsonValue) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect()
}

fn run_case(file: &str) {
    let case = golden(file);
    let arguments = strings(case.get("arguments").unwrap());
    let mut tokens = vec!["ar7".to_string()];
    tokens.extend(arguments.iter().cloned());
    let p = parser("ieipmain", IEIPMAIN).parse(&tokens).unwrap();
    let inputs = case.get("input_angstrom").unwrap().as_array().unwrap();
    let (first, second) = (bohr(&inputs[0]), bohr(&inputs[1]));
    let terms: Vec<Arc<dyn PesTerm>> = parse_biases(&p)
        .unwrap()
        .iter()
        .map(|spec| spec.build(&argon(&first)).unwrap())
        .collect();
    let settings = IeipSettings {
        max_iterations: p.get_usize("NSTEP", 999).unwrap(),
        beta: p.get_f64("BETA", 1.0).unwrap(),
        ..IeipSettings::default()
    };
    let mut pair = ElasticImagePair::new(settings, &first, &second).unwrap();
    let images = case.get("images_angstrom").unwrap().as_array().unwrap();
    let reports = case.get("reports").unwrap().as_array().unwrap();
    let betas = floats(case.get("beta").unwrap());
    let template = argon(&first);
    let surface = |x: &Col<f64>| {
        let sys = argon(x);
        let out = mop_units::lennard_jones(&sys, &EvalRequest::ENERGY_GRAD).unwrap();
        let (mut e, mut g) = (out.energy.value(), out.gradient_bohr.clone());
        let ctx = TermContext::new(0, &template, None);
        for term in &terms {
            let b = term.evaluate(&sys, &ctx, false).unwrap();
            e += b.energy.value();
            g += &b.gradient_bohr;
        }
        ImageValue {
            energy: out.energy.value(),
            gradient: out.gradient_bohr,
            biased_energy: e,
            biased_gradient: g,
        }
    };
    let mut worst = 0.0_f64;
    let mut k = 0;
    while let IeipAction::Evaluate([a, b]) = pair.ask() {
        let expected = images[k].as_array().unwrap();
        for (mine, theirs) in [(&a, &expected[0]), (&b, &expected[1])] {
            let theirs = bohr(theirs);
            for j in 0..theirs.nrows() {
                worst = worst.max((mine[j] - theirs[j]).abs());
            }
        }
        let report = pair.tell([surface(&a), surface(&b)]).unwrap();
        let reference = &reports[k];
        let energies = floats(reference.get("energy").unwrap());
        let biased = floats(reference.get("biased_energy").unwrap());
        for i in 0..2 {
            assert!(
                (report.values[i].energy - energies[i]).abs() < 1e-9,
                "{file} {k}"
            );
            assert!(
                (report.values[i].biased_energy - biased[i]).abs() < 1e-9,
                "{file} {k}"
            );
        }
        let step = report.step.as_ref().unwrap();
        assert!((step.beta - betas[k]).abs() < 1e-12, "{file} {k}");
        let separation = reference.get("separation_after").unwrap().as_f64().unwrap();
        assert!(
            (step.separation - separation).abs() < 1e-7,
            "{file} {k}: {} vs {separation}",
            step.separation
        );
        k += 1;
    }
    assert!(worst < 1e-7, "{file}: largest difference {worst:e} Bohr");
    assert_eq!(k, reports.len(), "{file}");
    let converged = case.get("converged").unwrap().as_bool().unwrap();
    assert_eq!(pair.end() == Some(IeipEnd::Converged), converged, "{file}");
    // The pair after the last step, which MultiOptPy wrote but did not evaluate.
    let last = images[k].as_array().unwrap();
    let [a, b] = pair.images();
    for (mine, theirs) in [(a, &last[0]), (b, &last[1])] {
        let theirs = bohr(theirs);
        for j in 0..theirs.nrows() {
            assert!((mine[j] - theirs[j]).abs() < 1e-7, "{file} last pair");
        }
    }
    eprintln!("{file}: {k} iterations, largest difference {worst:.2e} Bohr");
}

/// `-mi 3`: mopt-rs relaxes the images on their hyperspheres with gradients of the
/// coordinates it steps in (MultiOptPy does not; see the migration notes), so only the
/// outcome is compared: both converge in a similar number of iterations. (On this surface
/// the force in hyperspherical coordinates of radius 0.04 Bohr is below the tolerance 0.01
/// from the start, so mopt-rs does not move the images at all.)
#[test]
fn relaxation_on_hyperspheres_converges_as_multioptpy() {
    let case = golden("ieip_lj_ar7_micro.json");
    let plain = golden("ieip_lj_ar7_default.json");
    let inputs = case.get("input_angstrom").unwrap().as_array().unwrap();
    let (first, second) = (bohr(&inputs[0]), bohr(&inputs[1]));
    let mut outcome = Vec::new();
    for steps in [0, 3] {
        let settings = IeipSettings {
            max_iterations: 100,
            micro: mopt_rs::path::ieip::MicroSettings {
                steps,
                ..Default::default()
            },
            micro_coordinates: Some(mopt_rs::path::ieip::MicroCoordinates::polar(argon(&first))),
            ..IeipSettings::default()
        };
        let mut pair = ElasticImagePair::new(settings, &first, &second).unwrap();
        let mut evaluations = 0;
        let mut lowest_sum = Vec::new();
        while let IeipAction::Evaluate([a, b]) = pair.ask() {
            let value = |x: &Col<f64>| {
                let out = mop_units::lennard_jones(&argon(x), &EvalRequest::ENERGY_GRAD).unwrap();
                ImageValue::plain(out.energy.value(), out.gradient_bohr)
            };
            let report = pair.tell([value(&a), value(&b)]).unwrap();
            evaluations += 1;
            if report.step.is_some() {
                lowest_sum.push(report.values[0].energy + report.values[1].energy);
            }
        }
        assert_eq!(pair.end(), Some(IeipEnd::Converged), "-mi {steps}");
        outcome.push((pair.iteration(), evaluations, lowest_sum));
    }
    let theirs = case.get("reports").unwrap().as_array().unwrap().len();
    let without = plain.get("reports").unwrap().as_array().unwrap().len();
    eprintln!(
        "-mi 3: {} iterations, {} evaluations of pairs (MultiOptPy: {theirs} iterations; \
         without the relaxation {without})",
        outcome[1].0, outcome[1].1
    );
    assert_eq!(outcome[0].0, without);
    assert!(outcome[1].0.abs_diff(theirs) <= theirs / 2);
    assert!(outcome[1].1 >= outcome[1].0);
}

#[test]
fn default_settings_as_multioptpy() {
    run_case("ieip_lj_ar7_default.json");
}

#[test]
fn larger_beta_as_multioptpy() {
    run_case("ieip_lj_ar7_beta.json");
}

#[test]
fn bias_potential_as_multioptpy() {
    run_case("ieip_lj_ar7_bias.json");
}

/// The first structure is the higher one: the term of the energy difference acts the other
/// way round (MultiOptPy adds it to the first image and subtracts it from the second, along
/// the direction from the lower image to the higher).
#[test]
fn higher_structure_first_as_multioptpy() {
    run_case("ieip_lj_ar7_swapped.json");
}
